void QThreadData::clearEvents()
{
    // Event destructors may post new events (e.g. call deleteLater()), which
    // locks the mutex and modifies the list. So take the events out under the
    // lock and only delete them after unlocking; repeat until nothing new was
    // posted.
    for (;;) {
        QList<QPostEvent> events;
        {
            const auto locker = qt_scoped_lock(postEventList.mutex);
            if (postEventList.isEmpty())
                break;
            events.swap(postEventList);
            // we may be called from within sendPostedEvents()
            postEventList.startOffset = 0;
            postEventList.insertionOffset = 0;
            for (const QPostEvent &pe : std::as_const(events)) {
                if (pe.event) {
                    pe.receiver->d_func()->postedEvents.fetchAndSubRelaxed(1);
                    pe.event->m_posted = false;
                }
            }
        }
        for (const QPostEvent &pe : std::as_const(events))
            delete pe.event;
    }
}

